  "htmlOverview": "<style>\n  :root { --ac: #E040FB; --ac-light: #F0A8FF; --ac-rgb: 224, 64, 251; }\n  body { direction: rtl; }\n  .q-card { background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(224, 64, 251, 0.35); border-radius: 12px; padding: 14px 16px; margin-bottom: 22px; box-shadow: 0 4px 15px rgba(0,0,0,0.25); }\n  .q-title { font-size: 16.5px; font-weight: 700; color: #E040FB; margin-bottom: 8px; text-align: right; }\n  .q-text { font-size: 15px; color: #E040FB; line-height: 2.5; margin-bottom: 10px; font-weight: 700; text-align: right; }\n  .sol-box { background: rgba(0, 0, 0, 0.32); border-right: 3.5px solid #E040FB; border-radius: 8px; padding: 12px 16px; margin-top: 10px; }\n  .sol-title { font-size: 14px; font-weight: 700; color: #F0A8FF; margin-bottom: 6px; text-align: right; }\n  .sol-step { font-size: 15px; color: #E2E8F0; line-height: 2.5; text-align: right; }\n  .sol-step div { margin-top: 4px; margin-bottom: 4px; }\n  .lbl { color: #F0A8FF; font-weight: 700; }\n  .hl { color: #E040FB; font-weight: 700; }\n  .rev { text-align: justify; text-align-last: right; }\n  .pt { text-align: right; padding-right: 18px; position: relative; }\n  .pt::before { content: \"•\"; color: #E040FB; font-weight: 700; position: absolute; right: 2px; top: 0; }\n  .sec { color: #E040FB; font-weight: 700; font-size: 16px; margin-top: 12px !important; text-align: right; }\n  .exam { background: rgba(224, 64, 251, 0.10); border: 1.5px dashed #E040FB; border-radius: 8px; padding: 10px 12px; margin: 12px 0 4px; color: #FFFFFF; text-align: right; line-height: 2.2; }\n  .exam-t { color: #E040FB; font-weight: 700; font-size: 16px; display: block; margin-bottom: 2px; }\n  .tbl-wrap { width: 100%; overflow-x: auto; margin: 10px 0; }\n  .dt { width: 100%; border-collapse: collapse; font-size: 14px; direction: rtl; }\n  .dt th, .dt td { border: 1px solid rgba(255, 255, 255, 0.2); padding: 7px 9px; color: #FFFFFF; line-height: 2.35; text-align: right; vertical-align: middle; }\n  .dt th { background: rgba(224, 64, 251, 0.2); color: #F0A8FF; font-weight: 700; }\n  .dt tr:nth-child(even) td { background: rgba(255, 255, 255, 0.035); }\n  .box { border: 1.5px solid #E040FB; border-radius: 8px; padding: 10px 14px; text-align: right; color: #FFFFFF; }\n  .box-t { text-align: center; font-weight: 700; color: #F0A8FF; display: block; margin-bottom: 4px; }\n  .steps { margin: 10px 0; padding: 0; }\n  .step { display: block; line-height: 2.4; border-right: 3px solid #E040FB; background: rgba(224, 64, 251, 0.08); border-radius: 6px; padding: 6px 12px; margin: 8px 0; color: #FFFFFF; }\n  .step b { color: #F0A8FF; }\n  .ltr { direction: ltr; unicode-bidi: isolate; display: inline-block; }\n</style>\n<div style=\"padding: 4px 2px;\">\n\n  <div class=\"q-card\">\n    <div class=\"q-title\">✦ صنف کا تعارف: افسانہ</div><div class=\"sol-step\"><div class=\"rev\">اُردو میں <b>مختصر افسانہ</b> وہی نثری صنف ہے جسے انگریزی میں شارٹ اسٹوری کہتے ہیں۔ مغرب میں یہ انیسویں صدی کے وسط میں شروع ہوئی اور اُردو میں بیسویں صدی کے آغاز میں، جب داستانوں کا چلن ختم ہو چکا تھا۔</div><div class=\"rev\">افسانہ ایسی کہانی ہے جس میں زندگی کے <b>کسی ایک پہلو</b> کو دلچسپ انداز میں پیش کیا جائے۔ پلاٹ، کردار، عمل اور مکالمہ اس کے لازمی عناصر ہیں، اور تخیل و جذبہ اسے دلکش بناتے ہیں۔ ناول پوری زندگی کو وسعت سے پیش کرتا ہے، جبکہ افسانہ زندگی کے ایک گوشے کی جھلک دکھاتا ہے؛ اس کی پہچان <b>وحدتِ تاثر اور اختصار</b> ہے — اتنا مختصر کہ ایک ہی نشست میں پڑھا جا سکے۔</div><div class=\"rev\">اہم افسانہ نگار: پریم چند، علی عباس حسینی، سعادت حسن منٹو، عصمت چغتائی، راجندر سنگھ بیدی، کرشن چندر، غلام عباس، قرۃ العین حیدر اور انتظار حسین۔</div></div>\n  </div>\n\n  <div class=\"q-card\">\n    <div class=\"q-title\">✦ مصنف کا تعارف: پشکر ناتھ</div><div class=\"sol-step\"><div class=\"tbl-wrap\"><table class=\"dt\"><colgroup><col style=\"width:26%\"><col style=\"width:74%\"></colgroup><tr><th>پہلو</th><th>تفصیل</th></tr><tr><td>پیدائش</td><td>۳۱ مئی ۱۹۳۲ء، محلہ بٹہ یار، سری نگر</td></tr><tr><td>ملازمت</td><td>بی۔اے کے بعد سرکاری ملازمت؛ ایک مدت تک اکاؤنٹنٹ جنرل کے دفتر سے وابستہ؛ عمر کا زیادہ حصہ جموں میں گزرا</td></tr><tr><td>ادبی آغاز</td><td>۱۹۵۳ء میں رسالہ \"بیسویں صدی\" میں پہلا افسانہ \"کہانی پھر ادھوری رہی\"</td></tr><tr><td>افسانوی مجموعے</td><td>اندھیرے اُجالے، ڈل کے باسی، عشق کا چاند اندھیرا، کانچ کی دنیا (پہلے دو پر ریاستی کلچرل اکادمی کے انعامات)</td></tr><tr><td>دیگر</td><td>ریڈیائی اور اسٹیج ڈرامے بھی لکھے</td></tr><tr><td>وفات</td><td>جموں میں</td></tr></table></div><div class=\"rev\">اُن کی کہانیوں میں کشمیر کے مناظر، پھل پھول، دریا، جھرنے، چرند پرند اور موسم کا ذکر اکثر ملتا ہے، اور ان سے کشمیر کے دکھ درد کو سمجھنے میں مدد ملتی ہے۔ وہ الفاظ کا انتخاب بڑی احتیاط سے کرتے ہیں۔</div></div>\n  </div>\n\n  <div class=\"q-card\">\n    <div class=\"q-title\">✦ اہم نکات</div><div class=\"sol-step\"><div class=\"pt\">صنف: <b>افسانہ</b>؛ مصنف: <b>پشکر ناتھ</b>۔</div><div class=\"pt\">مرکزی کردار: <b>صمد جُو</b>، بنڈ (سری نگر) پر \"صمد اینڈ سنز، فریئرس اینڈ ٹیکسی ڈرمسٹ\" کا مالک۔</div><div class=\"pt\">فن: مردہ جانوروں کی کھالوں میں نیا جسم فٹ کرنا (ٹیکسی ڈرمی) — یہ فن اُس نے باپ <b>رمضان جُو</b> سے سیکھا۔</div><div class=\"pt\">علامت: <b>ہونٹوں کی خاموش تھرتھراہٹ</b> — محرومی اور بے بسی کی علامت۔</div><div class=\"pt\">چیتے کے بچے کی قیمت: پہلے <b>دو ہزار سات سو پچاس</b>، پھر لاگت پر <b>سترہ سو پچاس</b>؛ لڑکی نے پانچ سو کہے۔</div><div class=\"pt\">افسانے کا مقامی رنگ: کشمیر کا فطری حسن اور معاشرتی زندگی پس منظر کے طور پر۔</div></div>\n  </div>\n\n</div>",
